BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),f AS MATERIALIZED(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,ann_date,profit_dedt,q_dtprofit FROM raw_tushare.fina_indicator WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),years AS(SELECT generate_series(2024,2025) y),t AS MATERIALIZED(SELECT a.ts_code,y.y,f9.ann_date ann9,f12.ann_date ann12,f9.profit_dedt d9,f12.profit_dedt d12,f12.q_dtprofit q4 FROM base a CROSS JOIN years y LEFT JOIN f f9 ON f9.ts_code=a.ts_code AND f9.end_date=make_date(y.y,9,30) LEFT JOIN f f12 ON f12.ts_code=a.ts_code AND f12.end_date=make_date(y.y,12,31)),q AS(SELECT y,count(*) cohort_codes,count(*) FILTER(WHERE d9 IS NOT NULL AND d12 IS NOT NULL) cumulative_q4_valid,count(q4) direct_q4_valid,count(*) FILTER(WHERE d9 IS NOT NULL AND d12 IS NOT NULL AND q4 IS NOT NULL) overlap_codes,count(*) FILTER(WHERE d9 IS NOT NULL AND d12 IS NOT NULL AND q4 IS NOT NULL AND abs(q4-(d12-d9))<=1) agreement_within_1yuan,count(*) FILTER(WHERE d9 IS NOT NULL AND d12 IS NOT NULL AND q4 IS NOT NULL AND abs(q4-(d12-d9))>1) conflict_codes FROM t GROUP BY y),samples AS(SELECT t.ts_code,b.name,t.y,t.ann9,t.ann12 FROM t JOIN base b ON b.ts_code=t.ts_code WHERE t.d9 IS NOT NULL AND t.d12 IS NOT NULL AND t.q4 IS NOT NULL AND abs(t.q4-(t.d12-t.d9))>1 ORDER BY t.y,t.ts_code LIMIT 20)
SELECT jsonb_build_object('section','deducted_q4_consistency','as_of',current_timestamp,'data',(SELECT jsonb_agg(to_jsonb(q) ORDER BY y) FROM q),'conflict_samples',(SELECT jsonb_agg(to_jsonb(samples)) FROM samples));
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH base AS MATERIALIZED(SELECT ts_code,name FROM raw_tushare.stock_basic WHERE ts_code !~ '^(200|900)' AND list_status IN('L','P') AND list_date<=DATE '2026-10-30' AND(delist_date IS NULL OR delist_date>DATE '2026-10-30') AND ts_code NOT IN('002717.SZ','002827.SZ','601326.SH','605258.SH','688121.SH','688496.SH')),d AS(SELECT unnest(ARRAY[DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31']) end_date),i AS MATERIALIZED(SELECT ts_code,end_date,(CASE WHEN comp_type='1' THEN revenue ELSE total_revenue END) IS NOT NULL r_ok,n_income_attr_p IS NOT NULL p_ok FROM core_serving.equity_income WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),c AS MATERIALIZED(SELECT ts_code,end_date,n_cashflow_act IS NOT NULL c_ok FROM core_serving.equity_cashflow WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31')),f AS MATERIALIZED(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,profit_dedt IS NOT NULL d_ok FROM raw_tushare.fina_indicator WHERE end_date IN(DATE '2024-09-30',DATE '2024-12-31',DATE '2025-09-30',DATE '2025-12-31') ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),t AS(SELECT a.ts_code,count(*) FILTER(WHERE i.r_ok) r_periods,count(*) FILTER(WHERE i.p_ok) p_periods,count(*) FILTER(WHERE c.c_ok) c_periods,count(*) FILTER(WHERE f.d_ok) d_periods FROM base a CROSS JOIN d LEFT JOIN i ON i.ts_code=a.ts_code AND i.end_date=d.end_date LEFT JOIN c ON c.ts_code=a.ts_code AND c.end_date=d.end_date LEFT JOIN f ON f.ts_code=a.ts_code AND f.end_date=d.end_date GROUP BY a.ts_code)
SELECT jsonb_build_object('section','both_2024_2025_q4_inputs','as_of',current_timestamp,'eligible_codes',count(*),'revenue_both_years',count(*) FILTER(WHERE r_periods=4),'parent_profit_both_years',count(*) FILTER(WHERE p_periods=4),'ocf_both_years',count(*) FILTER(WHERE c_periods=4),'deducted_difference_both_years',count(*) FILTER(WHERE d_periods=4),'all_four_both_years',count(*) FILTER(WHERE r_periods=4 AND p_periods=4 AND c_periods=4 AND d_periods=4)) FROM t;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH r AS MATERIALIZED(SELECT ts_code,end_date,ann_date,update_flag,fetched_at,source_content_hash,profit_dedt FROM raw_tushare.fina_indicator WHERE end_date IN(DATE '2024-06-30',DATE '2024-09-30')),l AS(SELECT DISTINCT ON(ts_code,end_date) ts_code,end_date,ann_date,update_flag,profit_dedt FROM r ORDER BY ts_code,end_date,CASE update_flag WHEN '1' THEN 0 ELSE 1 END,ann_date DESC,fetched_at DESC,source_content_hash DESC),q AS(SELECT l.ts_code,l.end_date,l.ann_date,l.update_flag FROM l WHERE l.profit_dedt IS NULL AND EXISTS(SELECT 1 FROM r WHERE r.ts_code=l.ts_code AND r.end_date=l.end_date AND r.profit_dedt IS NOT NULL) ORDER BY l.end_date,l.ts_code LIMIT 20)
SELECT jsonb_build_object('section','selection_null_other_version_present','as_of',current_timestamp,'data',jsonb_agg(to_jsonb(q))) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH q AS(SELECT ts_code,end_date,ann_date,update_flag,fetched_at,profit_dedt IS NOT NULL deducted_nonnull,q_dtprofit IS NOT NULL quarter_deducted_nonnull FROM raw_tushare.fina_indicator WHERE ts_code IN('000100.SZ','000725.SZ','600519.SH') AND end_date=DATE '2026-09-30' ORDER BY ts_code,ann_date DESC,update_flag LIMIT 20)
SELECT jsonb_build_object('section','source_control_prod_rows','as_of',current_timestamp,'data',coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb)) FROM q;
COMMIT;
